changeSet.sql:
ALTER TABLE node_sources ADD COLUMN page_id UUID REFERENCES lib_pages(id) ON DELETE RESTRICT, ADD COLUMN range_start INTEGER, ADD COLUMN range_end INTEGER, ADD COLUMN pdf_file_id UUID REFERENCES library_files(file_id) ON DELETE RESTRICT, ADD COLUMN pdf_page_number INTEGER, ADD COLUMN pdf_bbox JSONB, ADD COLUMN image_region_id UUID REFERENCES lib_image_regions(id) ON DELETE RESTRICT;
ALTER TABLE node_sources ADD CONSTRAINT chk_node_sources_one_mode CHECK ( (page_id IS NOT NULL AND range_start IS NOT NULL AND range_end IS NOT NULL AND range_start >= 0 AND range_end > range_start AND pdf_file_id IS NULL AND image_region_id IS NULL) OR (pdf_file_id IS NOT NULL AND pdf_page_number IS NOT NULL AND pdf_bbox IS NOT NULL AND pdf_page_number >= 1 AND page_id IS NULL AND image_region_id IS NULL) OR (image_region_id IS NOT NULL AND page_id IS NULL AND pdf_file_id IS NULL) OR (page_id IS NULL AND pdf_file_id IS NULL AND image_region_id IS NULL) );
CREATE INDEX idx_node_sources_page_id ON node_sources(page_id) WHERE page_id IS NOT NULL; CREATE INDEX idx_node_sources_pdf_file_id ON node_sources(pdf_file_id) WHERE pdf_file_id IS NOT NULL; CREATE INDEX idx_node_sources_image_region_id ON node_sources(image_region_id) WHERE image_region_id IS NOT NULL;

rollback.sql:
DROP INDEX IF EXISTS idx_node_sources_image_region_id;
DROP INDEX IF EXISTS idx_node_sources_pdf_file_id;
DROP INDEX IF EXISTS idx_node_sources_page_id;
ALTER TABLE node_sources DROP CONSTRAINT IF EXISTS chk_node_sources_one_mode;
ALTER TABLE node_sources
    DROP COLUMN IF EXISTS image_region_id,
    DROP COLUMN IF EXISTS pdf_bbox,
    DROP COLUMN IF EXISTS pdf_page_number,
    DROP COLUMN IF EXISTS pdf_file_id,
    DROP COLUMN IF EXISTS range_end,
    DROP COLUMN IF EXISTS range_start,
    DROP COLUMN IF EXISTS page_id;
